package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsLeapFlag string // PIC X len=1 = "N"
var WsQ int64 // PIC 9(4) len=4 = 0
var WsR4 int64 // PIC 9(3) len=3 = 0
var WsR100 int64 // PIC 9(3) len=3 = 0
var WsR400 int64 // PIC 9(3) len=3 = 0
var WsMaxDay int64 // PIC 99 len=2 = 0
var WsValid int64 // PIC 99 len=2 = 0
var WsBadMonth int64 // PIC 99 len=2 = 0
var WsBadDay int64 // PIC 99 len=2 = 0

var DateRecData DateRec

var dateFileLines []string
var dateFileIdx int

func isInputDone() bool { return WsEofFlag == "Y" }
func isLeap() bool      { return WsLeapFlag == "Y" }

func modPow10(v int64, w int) int64 {
	m := int64(1)
	for i := 0; i < w; i++ {
		m *= 10
	}
	v = v % m
	if v < 0 {
		v += m
	}
	return v
}

func fmtNum(v int64, w int) string {
	v = modPow10(v, w)
	s := strconv.FormatInt(v, 10)
	if len(s) < w {
		s = strings.Repeat("0", w-len(s)) + s
	}
	if len(s) > w {
		s = s[len(s)-w:]
	}
	return s
}

func parseNum(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	// keep only digits sign? assume digits
	t = strings.TrimSpace(t)
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		// fallback: extract digits
		d := ""
		for _, c := range t {
			if c >= '0' && c <= '9' {
				d += string(c)
			}
		}
		if d == "" {
			return 0
		}
		n, _ = strconv.ParseInt(d, 10, 64)
	}
	return n
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseDateRec(line string) DateRec {
	rec := padRight(line, 12)
	var r DateRec
	r.DtId = rec[0:4]
	r.DtYyyy = parseNum(rec[4:8])
	r.DtMm = parseNum(rec[8:10])
	r.DtDd = parseNum(rec[10:12])
	return r
}

func MAINPARA() {
	f, err := os.ReadFile("input.dat")
	if err != nil {
		// COBOL OPEN INPUT on missing file would fail; treat missing as empty only if not exist?
		// Report error to stderr per spec
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	content := string(f)
	// Normalize line endings
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "\n")
	if content == "" {
		dateFileLines = []string{}
	} else {
		parts := strings.Split(content, "\n")
		// If file ends with newline, last element is "" beyond last record -> drop it
		if len(parts) > 0 && parts[len(parts)-1] == "" {
			parts = parts[:len(parts)-1]
		}
		dateFileLines = parts
	}
	dateFileIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE DATE-FILE (no-op)
	fmt.Fprintln(os.Stdout, "VALID: "+fmtNum(WsValid, 2)+" BAD MONTH: "+fmtNum(WsBadMonth, 2)+" BAD DAY: "+fmtNum(WsBadDay, 2))
}

func READPARA() {
	if dateFileIdx >= len(dateFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := dateFileLines[dateFileIdx]
	dateFileIdx++
	DateRecData = parseDateRec(line)
}

func PROCESSPARA() {
	LEAPPARA()
	if DateRecData.DtMm < 1 || DateRecData.DtMm > 12 {
		WsBadMonth = modPow10(WsBadMonth+1, 2)
		fmt.Fprintln(os.Stdout, DateRecData.DtId+" BAD MONTH "+fmtNum(DateRecData.DtMm, 2))
	} else {
		DAYSPARA()
		if DateRecData.DtDd < 1 || DateRecData.DtDd > WsMaxDay {
			WsBadDay = modPow10(WsBadDay+1, 2)
			fmt.Fprintln(os.Stdout, DateRecData.DtId+" BAD DAY "+fmtNum(DateRecData.DtDd, 2)+" MAX "+fmtNum(WsMaxDay, 2))
		} else {
			WsValid = modPow10(WsValid+1, 2)
			fmt.Fprintln(os.Stdout, DateRecData.DtId+" VALID "+fmtNum(DateRecData.DtYyyy, 4)+"-"+fmtNum(DateRecData.DtMm, 2)+"-"+fmtNum(DateRecData.DtDd, 2))
		}
	}
	READPARA()
}

func LEAPPARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	WsQ = modPow10(DateRecData.DtYyyy/4, 4)
	WsR4 = modPow10(DateRecData.DtYyyy%4, 3)
	WsQ = modPow10(DateRecData.DtYyyy/100, 4)
	WsR100 = modPow10(DateRecData.DtYyyy%100, 3)
	WsQ = modPow10(DateRecData.DtYyyy/400, 4)
	WsR400 = modPow10(DateRecData.DtYyyy%400, 3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYSPARA() {
	switch DateRecData.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}

func main() {
	WsEofFlag = "N"
	WsLeapFlag = "N"
	WsQ = 0
	WsR4 = 0
	WsR100 = 0
	WsR400 = 0
	WsMaxDay = 0
	WsValid = 0
	WsBadMonth = 0
	WsBadDay = 0
	MAINPARA()
}
